<?php
require_once 'config.php'; exigirLogin();
if (!temPerfil('admin')) { http_response_code(403); exit('Acesso restrito aos administradores.'); }
$tipo = (string) ($_GET['tipo'] ?? '');
$config = ['usuarios' => ['Usuários', 'usuarios.php'], 'treinamentos' => ['Treinamentos', 'treinamentos.php'], 'aulas' => ['Aulas', 'aulas.php'], 'pendentes' => ['Treinamentos pendentes', 'treinamentos.php'], 'materiais' => ['Materiais', 'materiais.php']];
if (!isset($config[$tipo])) { http_response_code(404); exit('Área administrativa não encontrada.'); }
if ($tipo === 'usuarios') { redirecionar('usuarios.php'); }
if ($tipo === 'materiais') { redirecionar('materiais.php'); }
[$titulo, $origem] = $config[$tipo]; $itens = [];
if ($tipo === 'usuarios') { $itens = $pdo->query('SELECT nome, email, perfil, ativo FROM usuarios ORDER BY nome')->fetchAll(); }
elseif ($tipo === 'treinamentos') { $itens = $pdo->query('SELECT t.titulo, t.status, t.carga_horaria, a.nome AS grupo FROM treinamentos t JOIN areas a ON a.id=t.area_id ORDER BY t.criado_em DESC')->fetchAll(); }
elseif ($tipo === 'pendentes') { $itens = $pdo->query("SELECT t.titulo, t.status, a.nome AS grupo FROM treinamentos t JOIN areas a ON a.id=t.area_id WHERE t.status = 'rascunho' ORDER BY t.criado_em DESC")->fetchAll(); }
elseif ($tipo === 'aulas') { $itens = $pdo->query('SELECT a.titulo, a.ordem, t.titulo AS grupo, a.duracao_min FROM aulas a JOIN treinamentos t ON t.id=a.treinamento_id ORDER BY t.titulo, a.ordem')->fetchAll(); }
else { $itens = $pdo->query('SELECT m.nome, m.tipo, m.tamanho_kb, a.titulo AS grupo FROM materiais m JOIN aulas a ON a.id=m.aula_id ORDER BY m.criado_em DESC')->fetchAll(); }
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TrainHub - <?php echo esc($titulo); ?></title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-100 min-h-screen text-slate-800"><main class="max-w-6xl mx-auto p-6 md:p-10"><div class="flex justify-between items-center mb-8"><div><a href="dashboard.php" class="text-blue-700 font-semibold">← Dashboard administrativo</a><h1 class="text-3xl font-bold mt-3"><?php echo esc($titulo); ?></h1><p class="text-slate-500">Área exclusiva para gerenciamento administrativo.</p></div><a href="logout.php" class="rounded-xl bg-slate-800 text-white px-4 py-2">Sair</a></div><section class="bg-white rounded-2xl shadow-sm overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-left"><thead class="bg-slate-800 text-white"><tr><?php if ($tipo === 'usuarios'): ?><th class="p-4">Nome</th><th class="p-4">E-mail</th><th class="p-4">Perfil</th><th class="p-4">Status</th><?php else: ?><th class="p-4">Nome</th><th class="p-4">Grupo</th><th class="p-4">Detalhes</th><?php endif; ?></tr></thead><tbody><?php if (!$itens): ?><tr><td colspan="4" class="p-6 text-slate-500">Nenhum item cadastrado.</td></tr><?php endif; ?><?php foreach ($itens as $item): ?><tr class="border-b"><td class="p-4 font-semibold"><?php echo esc($item['nome'] ?? $item['titulo']); ?></td><?php if ($tipo === 'usuarios'): ?><td class="p-4"><?php echo esc($item['email']); ?></td><td class="p-4"><?php echo esc($item['perfil']); ?></td><td class="p-4"><?php echo $item['ativo'] ? 'Ativo' : 'Bloqueado'; ?></td><?php else: ?><td class="p-4"><?php echo esc($item['grupo']); ?></td><td class="p-4"><?php echo esc($item['status'] ?? (($item['duracao_min'] ?? $item['tamanho_kb'] ?? 0) . ($tipo === 'aulas' ? ' min' : ' KB'))); ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></section><a href="<?php echo esc($origem); ?>" class="inline-block mt-6 rounded-xl bg-blue-700 text-white px-4 py-3">Abrir tela de cadastro</a></main></body></html>
